    "exercises": [
      {"q": "«Ahir va ploure a bots i barrals.» Què vol dir?", "o": ["Que va ploure moltíssim", "Que va ploure a estones", "Que només va plovisquejar"], "e": "Ploure a bots i barrals: ploure molt fort i en abundància."},
